fn reverse(v: &mut Vec<u64>) {
    let mut left = 0;
    let mut right = v.len().wrapping_sub(1); // Use wrapping_sub to avoid underflow

    while left < right {
        // Swap the elements at left and right indices
        v.swap(left, right);
        // Move the pointers towards the center
        left += 1;
        right = right.wrapping_sub(1); // Use wrapping_sub to avoid underflow
    }
}